function renderIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{if(el.firstChild)return;const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('class','icon');svg.setAttribute('aria-hidden','true');const path=document.createElementNS(svg.namespaceURI,'path');path.setAttribute('d',icons[el.dataset.icon]||icons.heart);svg.append(path);el.append(svg);});}
const education=[['FCPS (Feto-Maternal medicine)','2023','FCPS (Fellowship of the College of Physicians and Surgeons)'],['Community fellowship','2019','Young Gynaecology award and community fellowship 2019'],['FCPS (Gynae and Obstetrics)','2011','FCPS (Fellowship of the College of Physicians and Surgeons)'],['MBBS (Bachelor of Medicine, Bachelor of Surgery)','2003','Sir Salimullah Medical College'],['HSC (Higher Secondary Certificate)','1997','Mymensingh Girls Cadet College'],['SSC (Secondary School Certificate)','1995','Mymensingh Girls Cadet College']];
document.querySelector('#education-list').innerHTML=education.map(([title,year,degree],i)=>`<div class="education-item"><img src="assets/portrait${i%2?'2':''}.jpeg" alt="" loading="lazy"><div><h4>${title}</h4><div class="education-meta"><span><i data-icon="calendar"></i>${year}</span><span class="degree">${degree}</span></div></div></div>`).join('');
renderIcons();
const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
const revealObserver=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('in-view');revealObserver.unobserve(entry.target);}});},{threshold:.09});
document.querySelectorAll('.reveal').forEach(el=>revealObserver.observe(el));
const countObserver=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(!entry.isIntersecting)return;const el=entry.target,target=Number(el.dataset.count),suffix=el.dataset.suffix;countObserver.unobserve(el);if(reducedMotion)return;const start=performance.now();function tick(now){const progress=Math.min((now-start)/1500,1);el.textContent=Math.round(target*(1-Math.pow(1-progress,3)))+suffix;if(progress<1)requestAnimationFrame(tick);}requestAnimationFrame(tick);});},{threshold:.7});
document.querySelectorAll('[data-count]').forEach(el=>countObserver.observe(el));
const menuButton=document.querySelector('.menu-toggle'),nav=document.querySelector('#main-nav');
function closeMenu(){menuButton.setAttribute('aria-expanded','false');menuButton.setAttribute('aria-label','Open navigation');nav.classList.remove('open');}
menuButton.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')!=='true';menuButton.setAttribute('aria-expanded',String(open));menuButton.setAttribute('aria-label',open?'Close navigation':'Open navigation');nav.classList.toggle('open',open);});
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));
document.addEventListener('click',e=>{if(!e.target.closest('.header-inner'))closeMenu();});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu();});
const backTop=document.querySelector('.back-top');let scrollPending=false;
function updateScroll(){backTop.classList.toggle('visible',scrollY>700);const current=scrollY+180;let active='#home';for(const id of ['home','services','about','gallery']){if(document.getElementById(id).offsetTop<=current)active='#'+id;}nav.querySelectorAll('a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')===active));scrollPending=false;}
addEventListener('scroll',()=>{if(!scrollPending){requestAnimationFrame(updateScroll);scrollPending=true;}},{passive:true});updateScroll();
backTop.addEventListener('click',()=>scrollTo({top:0,behavior:reducedMotion?'instant':'smooth'}));
document.querySelectorAll('dialog').forEach(dialog=>{dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});dialog.addEventListener('close',()=>{document.body.style.overflow='';});});
function openDialog(dialog){dialog.showModal();document.body.style.overflow='hidden';}
const videoDialog=document.querySelector('#video-dialog'),videoPlayer=document.querySelector('#video-player');
document.querySelectorAll('[data-video]').forEach(button=>button.addEventListener('click',()=>{const frame=document.createElement('iframe');frame.src=`https://www.youtube-nocookie.com/embed/${button.dataset.video}?autoplay=1&rel=0`;frame.title=button.getAttribute('aria-label');frame.allow='autoplay; encrypted-media; picture-in-picture; fullscreen';frame.allowFullscreen=true;videoPlayer.replaceChildren(frame);openDialog(videoDialog);}));
videoDialog.addEventListener('close',()=>videoPlayer.replaceChildren());
const infoDialog=document.querySelector('#info-dialog'),infoContent=document.querySelector('#info-content');
document.querySelector('#biography-button').addEventListener('click',()=>{infoContent.innerHTML='<p class="eyebrow">Meet Your Specialist</p><h2>Dr. Runa Akhter Dola</h2><p>Assistant Professor in Feto-Maternal Medicine at Sir Salimullah Medical College and Mitford Hospital, Dhaka.</p><p>Dr. Dola specializes in high-risk pregnancy, feto-maternal medicine, and women’s health, with 16+ years of experience. Her work includes labor management, antenatal counseling, and infertility evaluation.</p><h3>Education &amp; Recognition</h3><p>MBBS, Sir Salimullah Medical College (2003); FCPS in Obstetrics and Gynaecology (2011); community fellowship in the Philippines (2019); and FCPS in Feto-Maternal Medicine (2023).</p><p>Recipient of the SS Ratnam Young Gynaecology award in 2019.</p><h3>Chamber</h3><p>Medinova Medical Services Ltd., Malibagh Branch.<br>Saturday, Monday &amp; Wednesday, 5:00 PM – 9:00 PM.</p><a class="button button-green" href="tel:+8801790118866">Call to Book an Appointment</a>';openDialog(infoDialog);});
document.querySelector('[data-faq]').addEventListener('click',e=>{e.preventDefault();infoContent.innerHTML='<p class="eyebrow">Before Your Visit</p><h2>Frequently Asked Questions</h2><details open><summary>How can I book an appointment?</summary><p>Call +880 1790-118866 or +880 1790-118855 to speak with the chamber and confirm an available appointment.</p></details><details><summary>Where is the chamber?</summary><p>Medinova Medical Services Ltd., Malibagh Branch, Gemcon Business Center, 255 New Circular Road, Malibagh More, Dhaka-1217.</p></details><details><summary>What are the consultation hours?</summary><p>Saturday, Monday and Wednesday, 5:00 PM to 9:00 PM. Please call the chamber to confirm before visiting.</p></details><details><summary>What should I bring to my consultation?</summary><p>Bring your previous prescriptions, test reports and ultrasound results, along with a list of medicines you currently take.</p></details>';openDialog(infoDialog);});
const reviewDialog=document.querySelector('#review-dialog');document.querySelector('#review-button').addEventListener('click',()=>openDialog(reviewDialog));
function addReview(review){const card=document.createElement('article');card.className='review-card';const quote=document.createElement('span');quote.className='quote-mark';quote.textContent='“';const message=document.createElement('blockquote');message.textContent=review.message;const stars=document.createElement('div');stars.className='stars';stars.textContent='★'.repeat(review.rating);stars.setAttribute('aria-label',`${review.rating} out of 5 stars`);const name=document.createElement('h3');name.textContent=review.name;const location=document.createElement('p');location.textContent=review.location+' · Local preview';card.append(quote,message,stars,name,location);document.querySelector('#reviews').append(card);}
let savedReviews=[];try{const saved=JSON.parse(localStorage.getItem('dola-preview-reviews')||'[]');if(Array.isArray(saved))savedReviews=saved.filter(r=>r&&typeof r.name==='string'&&typeof r.location==='string'&&typeof r.message==='string'&&Number.isInteger(r.rating)&&r.rating>=1&&r.rating<=5).slice(-12);savedReviews.forEach(addReview);}catch{}
document.querySelector('#review-form').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.target);const review={name:data.get('name').trim(),location:data.get('location').trim(),rating:Number(data.get('rating')),message:data.get('message').trim()};if(!review.name||!review.location||!review.message)return;addReview(review);savedReviews.push(review);let persisted=true;try{localStorage.setItem('dola-preview-reviews',JSON.stringify(savedReviews.slice(-12)));}catch{persisted=false;}reviewDialog.close();e.target.reset();const toast=document.querySelector('.toast');toast.textContent=persisted?'Thank you. Your preview review is saved in this browser.':'Thank you. Your preview review is visible for this visit.';toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),5000);});
